524:   /**
525:    * Procesa dirección y la separa en componentes
526:    */
527:   procesarDireccion(direccionCompleta: string) {    
528:     if (!direccionCompleta) return;
529:     
530:     try {
531:       const partes = direccionCompleta.split(' ');
532:       
533:       // Determinar si hay componentes de interior
534:       let tipoVia = '';
535:       let numeroVia = '';
536:       let numeroSecundario = '';
537:       let complementoDireccion = '';
538:       let tipoInterior1 = '';
539:       let numeroInterior1 = '';
540:       let tipoInterior2 = '';
541:       let numeroInterior2 = '';
542:       
543:       // Intentar extraer componentes básicos
544:       if (partes.length >= 1) tipoVia = partes[0];
545:       if (partes.length >= 2) numeroVia = partes[1];
546:       
547:       // Buscar índice del '#' para detectar número secundario
548:       const indicePound = partes.indexOf('#');
549:       if (indicePound > 0 && partes.length > indicePound + 1) {
550:         numeroSecundario = partes[indicePound + 1];
551:       } else if (partes.length >= 3) {
552:         // Alternativa si no hay '#' explícito
553:         numeroSecundario = partes[2];
554:       }
555:       
556:       // Buscar índice del '-' para complemento
557:       const indiceComplemento = partes.indexOf('-');
558:       if (indiceComplemento > 0 && partes.length > indiceComplemento + 1) {
559:         complementoDireccion = partes[indiceComplemento + 1];
560:       } else if (partes.length >= 4) {
561:         // Alternativa si no hay '-' explícito
562:         complementoDireccion = partes[3];
563:       }
564:       
565:       // Buscar componentes de interior (después de posibles comas)
566:       const direccionCompleta2 = direccionCompleta.split(',');
567:       
568:       if (direccionCompleta2.length >= 2) {
569:         const partesInterior1 = direccionCompleta2[1].trim().split(' ');
570:         if (partesInterior1.length >= 1) tipoInterior1 = partesInterior1[0];
571:         if (partesInterior1.length >= 2) numeroInterior1 = partesInterior1[1];
572:       }
573:       
574:       if (direccionCompleta2.length >= 3) {
575:         const partesInterior2 = direccionCompleta2[2].trim().split(' ');
576:         if (partesInterior2.length >= 1) tipoInterior2 = partesInterior2[0];
577:         if (partesInterior2.length >= 2) numeroInterior2 = partesInterior2[1];
578:       }
579:       
580:       // Actualizar formulario con los valores extraídos
581:       this.revisionForm.patchValue({
582:         tipoVia,
583:         numeroVia,
584:         numeroSecundario,
585:         complementoDireccion,
586:         tipoInterior1,
587:         numeroInterior1,
588:         tipoInterior2,
589:         numeroInterior2
590:       });
591:     } catch (e) {
592:       console.error('Error procesando dirección:', e);
593:       this.popUpManager.showErrorToast(this.translate.instant('formulario_pagador.ERROR.procesar_direccion'));
594:     }
595:   }
