597:   /**
598:    * Actualiza los validadores del formulario según la naturaleza seleccionada
599:    * @param naturaleza 'N' para natural, 'J' para jurídica
600:    */
601:   private actualizarValidadoresPorNaturaleza(naturaleza: string): void {
602:     const controles = {
603:       primerNombre: this.revisionForm.get('primerNombre'),
604:       segundoNombre: this.revisionForm.get('segundoNombre'),
605:       primerApellido: this.revisionForm.get('primerApellido'),
606:       segundoApellido: this.revisionForm.get('segundoApellido'),
607:       razonSocial: this.revisionForm.get('razonSocial'),
608:       digito_verificacion: this.revisionForm.get('digito_verificacion')
609:     };
610:     
611:     if (naturaleza === 'J') { // Jurídica
612:       controles.primerNombre?.clearValidators();
613:       controles.segundoNombre?.clearValidators();
614:       controles.primerApellido?.clearValidators();
615:       controles.segundoApellido?.clearValidators();
616:       controles.razonSocial?.setValidators([Validators.required, Validators.maxLength(100)]);
617:     } else { // Natural
618:       controles.primerNombre?.setValidators([Validators.required]);
619:       controles.primerApellido?.setValidators([Validators.required]);
620:       controles.razonSocial?.clearValidators();
621:       controles.digito_verificacion?.clearValidators();
622:     }
623: 
624:     // Actualizar validez de controles
625:     Object.values(controles).forEach(control => control?.updateValueAndValidity());
626:   }
