628:   /**
629:    * Inactiva un registro existente
630:    */
631:   private inactivarRegistro(registro: any): Promise<void> {
632:     return new Promise((resolve, reject) => {
633:       const secuencia = parseInt(registro.TERPA_SECUENCIA, 10);
634:       const añoPago = parseInt(this.data.anioRecibo.split('/')[1]);
635:       
636:       // Crear objeto minimalista solo con la información necesaria
637:       const datosRequest = {
638:         _puttercero_pago_secuencia: {
639:           TERPA_SECUENCIA: secuencia,
640:           TERPA_ANO_PAGO: añoPago,
641:           TERPA_ESTADO_REGISTRO: "I"
642:         }
643:       };
644:       
645:       
646:       // Hacer petición PUT
647:     this.facturacionElectronicaService.put(`tercero_pago/${secuencia}`, datosRequest).subscribe({
648:       next: (response: any) => {
649:         if (response && response.Success) {
650:           resolve();
651:         } else {
652:           reject(new Error('Error al inactivar el registro existente'));
653:         }
654:       },
655:       error: (error: HttpErrorResponse) => {
656:         reject(error);
657:       }
658:     });
659:   });
660:   }
