662:   /**
663:    * Crea un nuevo registro de pagador
664:    */
665:   private crearNuevoRegistro(numeroRecibo: string): Promise<void> {
666:     return new Promise((resolve, reject) => {
667:       const formValues = this.revisionForm.value;
668:       const añoPago = this.data.anioRecibo.split('/')[1];
669:       
670:       // Formatear fecha
671:       const fechaActual = new Date();
672:       const fechaFormateada = `${fechaActual.getDate().toString().padStart(2, '0')}/${
673:         (fechaActual.getMonth() + 1).toString().padStart(2, '0')}/${
674:         fechaActual.getFullYear()}`;
675:       
676:       // Construir dirección
677:       const direccionFormateada = this.construirDireccionFormateada();
678:       
679:       // Crear objeto de datos
680:       const pagador: any = {
681:         TERPA_SECUENCIA: parseInt(numeroRecibo, 10),
682:         TERPA_ANO_PAGO: parseInt(añoPago),
683:         TERPA_NATURALEZA: formValues.naturaleza,
684:         TERPA_TDO_CODVAR: formValues.tipoDocumento,
685:         TERPA_NRO_DOCUMENTO: parseInt(formValues.numeroDocumento, 10),
686:         TERPA_DIGITO_CHEQUEO: formValues.digito_verificacion ? parseInt(formValues.digito_verificacion, 10) : null,
687:         TERPA_DIRECCION: direccionFormateada.toUpperCase(),
688:         TERPA_TELEFONO: parseInt(formValues.telefono, 10),
689:         TERPA_EMAIL: formValues.correo,
690:         TERPA_ESTADO_REGISTRO: "A",
