17:   private numPendientesSubject = new BehaviorSubject(0);
18:   public numPendientes$ = this.numPendientesSubject.asObservable();
19: 
20:   private menuActivoSubject = new BehaviorSubject(false);
21:   public menuActivo$ = this.menuActivoSubject.asObservable();
22: 
23:   private loading = new BehaviorSubject(false);
24:   public loading$ = this.loading.asObservable();
25: 
26:   private notificacionSubject = new BehaviorSubject<any>(null);
27:   public notificacion$ = this.notificacionSubject.asObservable();
28: 
29:   public notificacionesNoLeidas: any = [];
30:   public notificacionesLeidas: any = [];
31: 
32:   private socket$: WebSocketSubject<any> | undefined;
33:   
34:   private ws: string | undefined;
35:   private crud: string | undefined;
36:   private documentoUsuario: string | undefined;
37: 
38:   constructor(private confService: ConfiguracionService) {
39:     //Cerrar el panel de notificaciones al hacer clic por fuera de el
40:     fromEvent<KeyboardEvent>(document, 'mouseup').subscribe(
41:       (data: KeyboardEvent) => {
42:         if (this.menuActivoSubject) {
43:           if (
44:             data
45:               .composedPath()
46:               .map((info: any) => info.localName)
47:               .filter((dataFilter: any) => dataFilter === 'ng-uui-notioas')
48:               .length === 0
49:           ) {
50:             this.closePanel();
51:           }
52:         }
53:       }
54:     );
55:   }
56: 
57:   // Conexión por WebSocket
58:   connectWebSocket(docUsuario:string){
59:     if (!this.ws) {
60:       console.error('URL del WebSocket no está definida');
61:       return;
62:     }
63: 
64:     this.socket$ = new WebSocketSubject(this.ws);
65: 
66:     this.socket$.subscribe((notificacion) => {
67:       this.numPendientes++;
68:       this.numPendientesSubject.next(this.numPendientes);
69:       this.notificacionesNoLeidas.unshift(notificacion);
70:       this.updateNotifications();
71:     });
72: 
73:     // Enviar el docuemento de usuario al servidor cuando se establezca la conexión
74:     this.socket$.next(docUsuario + "wc");
75:   }
76: 
77:   toogleMenuNotify(): void {
78:     this.menuActivoSubject.next(true);
79:   }
80: 
81:   closePanel(): void {
82:     this.menuActivoSubject.next(false);
83:   }
84: 
85:   init(usuario: any): void {
86:     this.ws = environment.NOTIFICACION_MID_WS;
87:     this.crud = environment.NOTIFICACIONES_CRUD;
88:     this.documentoUsuario = usuario.userService?.documento;
89:     if (this.documentoUsuario) {            
90:       this.connectWebSocket(this.documentoUsuario);
91:       this.queryNotifications();
92:     }
93:   }
94: 
95:   // Actualizar lista de notificaciones
96:   updateNotifications(): void {
97:     this.notificaciones = [...this.notificacionesNoLeidas, ...this.notificacionesLeidas];
98:     this.notificacionesSubject.next(this.notificaciones);
99:   }
100: 
101:   // Actualizar notificación
102:   changeStateToView(notificacion: any): void {
103:     if (!notificacion.lectura) {
104:       this.loading.next(true);
105:       this.numPendientes--;
106:       this.numPendientesSubject.next(this.numPendientes);
107: 
108:       this.confService.putWithoutPath(`${this.crud}notificacion/${notificacion._id}`, {}).subscribe(
109:         (res: any) => {
110:           if (res?.Data) {
111:             notificacion.lectura = true;  // Cambiar el estado de la notificación a leida
112: 
113:             // Eliminar notificación de la lista de notificaciones no leidas
114:             this.notificacionesNoLeidas = this.notificacionesNoLeidas.filter(
115:               (no_leida:any) => no_leida._id !== notificacion._id
116:             );
117: 
118:             // Agregar notificación al inicio de las notificaciones leidas 
119:             this.notificacionesLeidas.unshift(notificacion); 
120: 
121:             // Mantener únicamente 5 notificaciones leidas
122:             if (this.notificacionesLeidas.length > 5) {
123:               this.notificacionesLeidas.pop();
124:             }
125:                                   
126:             this.updateNotifications();
127:             this.loading.next(false);
128:             setTimeout(() => this.closePanel(), 1000);
129:           }
130:         }, 
131:         (error: any) => {
132:           console.error(error);
133:           this.loading.next(false);
134:           setTimeout(() => this.closePanel(), 1000);
135:         }
136:       )
137:     }
138:     this.notificacionSubject.next(notificacion);
139:   }
140: 
141:   // Consultar listado de notificaciones
142:   queryNotifications(): void {
143:     if (this.documentoUsuario === "") {
144:       this.loading.next(false);
145:       return;
146:     }
147: 
148:     this.loading.next(true);
149: 
150:     const query = `notificacion?query=destinatario:${this.documentoUsuario}`;
151:     const noLeidasQuery = `,lectura:false,&sortby=fecha_creacion&order=desc&limit=0`;
152:     const leidasQuery = `,lectura:true,&sortby=fecha_lectura&order=desc&limit=5`;
153: 
154:     this.confService.getWithoutPath(`${this.crud}${query + noLeidasQuery}`).subscribe(
155:       (res: any) => {
156:         if (res?.Data) {
157:           this.notificacionesNoLeidas = res.Data;
158:           this.numPendientes = res.Data.length;
159:           
160:           this.confService.getWithoutPath(`${this.crud}${query + leidasQuery}`).subscribe(
161:             (res: any) => {
162:               if (res?.Data) {
163:                 this.notificacionesLeidas = res.Data;
164:                 this.numPendientesSubject.next(this.numPendientes);
165:                 this.updateNotifications();
166:               }
167:             }, (error: any) => {
168:               console.error(error);
169:               this.loading.next(false);
170:             }
171:           )
172:         }
173:         this.loading.next(false);
174:       }, (error: any) => {
175:         console.error(error);
176:         this.loading.next(false);
177:       }
178:     )
179:   }
180: }

