31:     const coreUrl = `${coreBase}assets/i18n/${lang}.json`;
32:     const urls = Array.from(new Set([rootUrl, coreUrl]));
33: 
34:     return forkJoin(
35:       urls.map((url) =>
36:         this.http
37:           .get<Record<string, unknown>>(url)
38:           .pipe(catchError(() => of({})))
39:       )
40:     ).pipe(
41:       map((translations) =>
42:         translations.reduce(
43:           (merged, current) => ({ ...merged, ...current }),
44:           {}
45:         )
46:       )
47:     );
48:   }
49: }
50: 
51: export function createTranslateLoader(handler: HttpBackend) {
52:   return new CoreTranslateLoader(new HttpClient(handler));
53: }
54: 
55: export const appConfig: ApplicationConfig = {
56:   providers: [
57:     provideRouter(routes),
58:     { provide: APP_BASE_HREF, useValue: '/' },
59:     BrowserAnimationsModule,
60:     provideAnimations(),
61:     getSingleSpaExtraProviders(),
62:     provideHttpClient(withFetch(), withInterceptors([authInterceptor])),
63:     // Configuración de MatDialog
64:     MatDialog,
65:     Overlay,
66:     {
67:       provide: MAT_DIALOG_DEFAULT_OPTIONS,
68:       useValue: {
69:         hasBackdrop: true,
70:         disableClose: false,
71:         width: '800px'
72:       }
73:     },
74:     TranslateModule.forRoot({
75:       defaultLanguage: 'es',
76:       loader: {
77:         provide: TranslateLoader,
78:         deps: [HttpBackend],
79:         useFactory: createTranslateLoader
80:       }
81:     }).providers!
82:   ]
83: };

